input.oldString:
// Stub implementation to satisfy contract and avoid errors.
    const W = 800, H = 600;
    const player = { x: W/2, y: H/2, vx: 0, vy: 0 };
    let score = 0;
    let state = "menu"; // "menu" | "playing" | "gameover"
    const objective = "Flip momentum to avoid spikes coming from the direction you travel.";
    function publishState() {
      window.__game = {
        state,
        score,
        player: {
          x: player.x,
          y: player.y,
          visible: true
        },
        objective
      };
    }
    // Initial publish before any rendering.
    publishState();
    // Minimal render to ensure canvas is not blank.
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    function render() {
      ctx.fillStyle = '#05050c';
      ctx.fillRect(0,0,W,H);
      // draw player dot
      ctx.fillStyle = '#7df9ff';
      ctx.beginPath();
      ctx.arc(player.x, player.y, 4, 0, Math.PI*2);
      ctx.fill();
    }
    function start() {
      state = "playing";
      publishState();
      render();
    }
    // Restart handling
    function reset() { location.reload(); }
    document.addEventListener('keydown', (e) => { if (e.key === 'r' || e.key === 'R') reset(); });
    document.getElementById('restart').addEventListener('click', reset);
    // Start immediately
    start();

